// checker_engine_tests.js — QuickJS 引擎差分测试脚本
//
// tests/checker.c 是单文件 QuickJS-NG 应用（内嵌字节码的特判程序）。它的 main
// 只执行内嵌脚本，常规的运行对比覆盖不到引擎本体。run_tests.sh 用它派生出一个
// “执行命令行指定 JS 文件”的运行器（把 main 换成 JS_Eval 一个脚本），让原版与
// 各混淆版本都执行本脚本，stdout / stderr / 退出码必须逐字节一致。
//
// 约束：输出必须确定——不打印当前时间、随机数、耗时或任何依赖地址的信息。
'use strict';

let sections = 0, cases = 0;
const out = [];
function show(...args) {
    out.push(args.map(a => {
        if (typeof a === 'string') return a;
        if (typeof a === 'bigint') return a + 'n';
        if (a === undefined) return 'undefined';
        if (typeof a === 'number' && Object.is(a, -0)) return '-0';
        if (typeof a === 'number' && Number.isNaN(a)) return 'NaN';
        try { return JSON.stringify(a) ?? String(a); } catch (e) { return String(a); }
    }).join(' '));
}
function T(name, fn) {
    cases++;
    try {
        const r = fn();
        if (r && typeof r.then === 'function') {
            pending++;
            r.then(v => show('ok  ', name, v === undefined ? '' : v),
                   e => show('rej ', name, err(e)));
            return;
        }
        show('ok  ', name, r === undefined ? '' : r);
    } catch (e) {
        show('thr ', name, err(e));
    }
}
function err(e) {
    if (e instanceof Error) {
        // SyntaxError 的位置信息含脚本名，只保留行列与正文
        const msg = String(e.message).replace(/\(.*?:(\d+):(\d+)\)/g, '($1:$2)');
        return (e.constructor && e.constructor.name) + ': ' + msg;
    }
    return 'throw<' + typeof e + '>: ' + String(e);
}
function section(title) { sections++; show('\n## ' + title); }
let pending = 0;
// 子表达式各自可能抛异常的用例：逐个求值，异常转成文字，避免一处抛出掩盖后面的结果
function S(fn) {
    try { const v = fn(); return typeof v === 'string' ? v : JSON.stringify(v) ?? String(v); }
    catch (e) { return err(e); }
}

